const languageSelect = document.querySelector('#languageSelect');
const menuToggle = document.querySelector('.menu-toggle');
const navPanel = document.querySelector('.nav-panel');
const taskComposer = document.querySelector('#taskComposer');
const taskInput = document.querySelector('#taskInput');
let activeLocale = 'pt-BR';

const setText = (selector, value) => { const element = document.querySelector(selector); if (element) element.textContent = value; };
const setHtml = (selector, value) => { const element = document.querySelector(selector); if (element) element.innerHTML = value; };

function applyLanguage(locale) {
  if (document.querySelector('#photoSurvey')) {
    activeLocale = salesTranslations[locale] ? locale : 'pt-BR';
    document.documentElement.lang = activeLocale;
    setText('#authOpen', salesTranslations[activeLocale].nav[4]);
    document.querySelector('.language-control').hidden = false;
    languageSelect.setAttribute('aria-label', salesTranslations[activeLocale].language);
    document.querySelector('.language-control .sr-only').textContent = salesTranslations[activeLocale].language;
    menuToggle.setAttribute('aria-label', navPanel.classList.contains('open') ? salesTranslations[activeLocale].menu[1] : salesTranslations[activeLocale].menu[0]);
    localStorage.setItem('facilise-language', activeLocale);
    window.dispatchEvent(new CustomEvent('facilise:languagechange'));
    return;
  }
  const text = salesTranslations[locale] || salesTranslations['pt-BR'];
  activeLocale = salesTranslations[locale] ? locale : 'pt-BR';
  document.documentElement.lang = activeLocale;
  document.title = text.meta[0];
  document.querySelector('meta[name="description"]').content = text.meta[1];
  document.querySelectorAll('.nav-panel > a').forEach((item, index) => { item.textContent = text.nav[index]; });
  setText('#authOpen', text.nav[4]);
  setHtml('.hero-copy .eyebrow', `<span class="eyebrow-dot"></span> ${text.hero[0]}`);
  setHtml('.hero-copy h1', `${text.hero[1]}<br><span>${text.hero[2]}</span>`);
  setText('.hero-text', text.hero[3]);
  setHtml('.hero-actions .primary', `${text.hero[4]} <span>→</span>`); setText('.hero-actions .secondary', text.hero[5]);
  setText('.founding-note strong', text.hero[6]); setText('.founding-note span', text.hero[7]);
  document.querySelectorAll('.sales-proof span').forEach((item, index) => { item.textContent = text.benefits[index]; });
  setHtml('.online-badge', `<i></i> ${text.preview[0]}`); setText('.board-label', text.preview[1]);
  document.querySelectorAll('.software-board article').forEach((item, index) => { const row = text.preview[index + 2]; item.querySelector('strong').textContent = row[0]; item.querySelector('small').textContent = row[1]; item.querySelector('b').textContent = row[2]; });
  const stats = document.querySelectorAll('.preview-stats > div'); stats[0].querySelector('span').textContent = text.preview[5]; stats[0].querySelector('strong').textContent = text.preview[6]; stats[1].querySelector('span').textContent = text.preview[7];
  document.querySelectorAll('.proof-strip span').forEach((item, index) => { item.textContent = text.proof[index]; });
  setText('.task-section .eyebrow', text.included[0]); setHtml('.task-section h2', text.included[1]); setText('.task-section .section-heading > p:last-child', text.included[2]);
  document.querySelectorAll('.task-card').forEach((card, index) => { const content = text.cards[index]; card.querySelector(':scope > span').textContent = content[0]; card.querySelector('h3').textContent = content[1]; card.querySelector('p').textContent = content[2]; });
  setText('.how-copy .eyebrow', text.how[0]); setText('.how-copy h2', text.how[1]); setText('.how-copy > p:not(.eyebrow)', text.how[2]); setHtml('.how-copy .text-link', `${text.how[3]} <span>→</span>`);
  document.querySelectorAll('.flow-list li').forEach((step, index) => { step.querySelector('h3').textContent = text.steps[index][0]; step.querySelector('p').textContent = text.steps[index][1]; });
  setText('.pricing-copy .eyebrow', text.pricing[0]); setHtml('.pricing-copy h2', text.pricing[1]); setText('.pricing-copy > p', text.pricing[2]); document.querySelectorAll('.pricing-copy li').forEach((item, index) => { item.textContent = text.pricing[3][index]; }); setText('.price-badge', text.pricing[4]); setText('.price-card > p', text.pricing[5]); setHtml('.price-card .btn', `${text.pricing[6]} <span>→</span>`); setText('.price-card > small', text.pricing[7]);
  setText('.security-grid > div:first-child .eyebrow', text.faq[0]); setText('.security-grid > div:first-child h2', text.faq[1]);
  document.querySelectorAll('.security-items article').forEach((item, index) => { item.querySelector('h3').textContent = text.faq[index + 2][0]; item.querySelector('p').textContent = text.faq[index + 2][1]; });
  setText('.final-cta .eyebrow', text.cta[0]); setText('.final-cta h2', text.cta[1]); setText('.final-cta p:not(.eyebrow)', text.cta[2]); setHtml('#ctaAuthOpen', `${text.cta[3]} <span>→</span>`);
  setHtml('.footer-top > p', `${text.footer[0]}<br>${text.footer[1]}`); setText('.footer-bottom > span', text.footer[2]); document.querySelectorAll('.footer-bottom a').forEach((item, index) => { item.textContent = text.footer[index + 3]; });
  languageSelect.setAttribute('aria-label', text.language); document.querySelector('.language-control .sr-only').textContent = text.language;
  menuToggle.setAttribute('aria-label', navPanel.classList.contains('open') ? text.menu[1] : text.menu[0]);
  localStorage.setItem('facilise-language', activeLocale);
  window.dispatchEvent(new CustomEvent('facilise:languagechange'));
}

function resolveInitialLanguage() {
  const saved = localStorage.getItem('facilise-language');
  if (salesTranslations[saved]) return saved;
  return 'pt-BR';
}

languageSelect.addEventListener('change', (event) => applyLanguage(event.target.value));
menuToggle?.addEventListener('click', () => { const isOpen = navPanel.classList.toggle('open'); menuToggle.setAttribute('aria-expanded', String(isOpen)); menuToggle.setAttribute('aria-label', salesTranslations[activeLocale].menu[isOpen ? 1 : 0]); });
navPanel?.querySelectorAll('a').forEach((link) => link.addEventListener('click', () => { navPanel.classList.remove('open'); menuToggle?.setAttribute('aria-expanded', 'false'); }));

document.addEventListener('click', (event) => { const prompt = event.target.closest('[data-task]'); if (!prompt || !taskInput) return; taskInput.value = prompt.dataset.task; taskInput.focus(); });
document.querySelectorAll('[data-fill-task]').forEach((link) => link.addEventListener('click', () => { taskInput.value = link.dataset.fillTask; window.setTimeout(() => taskInput.focus(), 400); }));
document.querySelectorAll('.schedule-options button').forEach((option) => option.addEventListener('click', () => { document.querySelectorAll('.schedule-options button').forEach((item) => item.classList.remove('selected')); option.classList.add('selected'); }));

function showTaskToast(message) {
  let toast = document.querySelector('.task-toast');
  if (!toast) { toast = document.createElement('div'); toast.className = 'task-toast'; toast.setAttribute('role', 'status'); toast.innerHTML = '<span>✦</span><p></p>'; document.body.appendChild(toast); }
  toast.querySelector('p').textContent = message; toast.classList.add('show'); window.clearTimeout(showTaskToast.timer); showTaskToast.timer = window.setTimeout(() => toast.classList.remove('show'), 4200);
}

taskComposer?.addEventListener('submit', (event) => { event.preventDefault(); const task = taskInput.value.trim(); const text = pageTranslations[activeLocale]; if (!task) { taskInput.focus(); showTaskToast(text.toast[0]); return; } showTaskToast(`${text.toast[1]} “${task}”. ${text.toast[2]}`); window.setTimeout(() => document.querySelector('#authOpen')?.click(), 900); });
document.querySelector('#ctaAuthOpen')?.addEventListener('click', () => {
  document.querySelector('#authOpen')?.click();
  document.querySelector('[data-auth-go="register"]')?.click();
});
document.querySelectorAll('.sales-signup').forEach((button) => button.addEventListener('click', () => {
  document.querySelector('#authOpen')?.click();
  document.querySelector('[data-auth-go="register"]')?.click();
}));

const initialLanguage = resolveInitialLanguage();
languageSelect.value = initialLanguage;
applyLanguage(initialLanguage);
